import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.BZO4qERu.js";const y=JSON.parse('{"title":"Use your own keys","description":"","frontmatter":{},"headers":[],"relativePath":"online/byok.md","filePath":"online/byok.md","lastUpdated":1792570296000}'),n={name:"online/byok.md"};function s(i,e,l,d,c,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="use-your-own-keys" tabindex="-1">Use your own keys <a class="header-anchor" href="#use-your-own-keys" aria-label="Permalink to &quot;Use your own keys&quot;">​</a></h1><p>Run tasks with your own model and data-source keys instead of PaperSeek Service. Tasks with your own keys use no credits; provider charges and rate limits belong to your own provider accounts.</p><h2 id="set-up-your-keys" tabindex="-1">Set up your keys <a class="header-anchor" href="#set-up-your-keys" aria-label="Permalink to &quot;Set up your keys&quot;">​</a></h2><ol><li>Select <strong>Your own key</strong> from the account menu at the bottom of the sidebar.</li><li>In <strong>Settings › Model service</strong>, choose <strong>Add connection</strong>, fill in the model details and key, then click <strong>Save</strong> (see <a href="./../guide/models">Models &amp; ranking</a>).</li><li>In <strong>Settings › Data sources</strong>, choose <strong>Configure</strong> (or <strong>Configure key</strong>) for a source and save its key. With your own key, every source that takes a key requires one, including OpenAlex, PubMed, and Semantic Scholar; arXiv, Crossref, and PaperHub work without one.</li></ol><p>Model keys and data-source keys are separate. A model API key does not grant access to a literature database.</p><h2 id="public-endpoints-only" tabindex="-1">Public endpoints only <a class="header-anchor" href="#public-endpoints-only" aria-label="Permalink to &quot;Public endpoints only&quot;">​</a></h2><p>Online, only public model endpoints are accepted. Localhost, <code>127.0.0.1</code>, private network addresses, and other non-public destinations are blocked. To use a model on your own machine or network, run the <a href="./../self-hosting/">Community edition</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./privacy">Data &amp; privacy</a> — how saved keys are stored and who can see them.</li><li><a href="./credits">Service &amp; credits</a> — the alternative: PaperSeek-provided models.</li></ul>',9)])])}const p=o(n,[["render",s]]);export{y as __pageData,p as default};
